script:
(function () {
  'use strict';
  // Payments on a home equity line of credit balance (no new draws), month by month.
  //   Rate in month m = start rate + yearly change x floor((m - 1) / 12), kept between 0% and the cap.
  //   Interest each month = balance x rate / 12.
  //   Draw period (D months): minimum = interest only, interest + 1% of the balance, or 1% / 1.5% / 2%
  //   of the balance (never below that month's interest), and never below the dollar minimum; plus any
  //   extra principal; capped at what is owed.
  //   Repayment period (n months): level payment P = B x i / (1 - (1 + i)^-k) on the balance B and the
  //   k months left, re-figured whenever the rate changes (P = B / k at 0%); or equal principal
  //   (balance at the start of repayment / n) plus that month's interest. Extra principal is added.
  // Verified in Node (scratchpad b6mtg/eq.test.js): $50,000 at 8.5% with no rate change: interest-only
  //   $354.17, then $433.91 a month for 240 months (closed form), balance $0 at month 300 and total
  //   interest $75,388.79 = 60 x 354.17 + 240 x M - 50,000 (closed form, to the cent); equal principal starts at
  //   $208.33 + $354.17 = $562.50 and falls by $1.48 a month; with +0.25% a year the rate is 9.75% in
  //   month 61 -> $474.26 over 240 months, and $482.25 at 10% in month 73 on the balance left over 228
  //   months (both closed form); the rate stops at the cap;
  //   interest + 1% of balance on $50,000 = $854.17 first month; 0% rate -> B / n; extra principal
  //   pays off sooner with less interest; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAs) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAs === undefined ? NaN : blankAs;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function level(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return balance;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // o: balance, rate, draw, repay (months), rule, method, change, cap, floor, extra.
  function run(o) {
    var bal = o.balance, rows = [], interestTotal = 0, paid = 0, prevRate = -1, pay = 0, principalPart = 0;
    var total = o.draw + o.repay, endDraw = o.draw === 0 ? o.balance : null;
    for (var m = 1; m <= total && bal > 0.005; m++) {
      var rate = Math.min(o.cap, Math.max(0, o.rate + o.change * Math.floor((m - 1) / 12)));
      rate = Math.round(rate * 100000) / 100000;
      var interest = bal * rate / 1200, payment, inDraw = m <= o.draw;
      if (inDraw) {
        if (o.rule === 'io') payment = interest;
        else if (o.rule === 'int1') payment = interest + bal * 0.01;
        else payment = Math.max(interest, bal * (o.rule === 'p1' ? 0.01 : o.rule === 'p15' ? 0.015 : 0.02));
        payment = Math.max(payment, o.floor) + o.extra;
      } else {
        var left = total - m + 1;
        if (m === o.draw + 1) principalPart = bal / o.repay;
        if (o.method === 'level') {
          if (m === o.draw + 1 || rate !== prevRate) pay = level(bal, rate, left);
          payment = pay + o.extra;
        } else {
          payment = principalPart + interest + o.extra;
        }
        if (m === total) payment = bal + interest;
      }
      payment = Math.min(payment, bal + interest);
      var principal = payment - interest;
      bal -= principal;
      if (bal < 0.005) bal = 0;
      interestTotal += interest; paid += payment;
      prevRate = rate;
      rows.push({ month: m, draw: inDraw, rate: rate, payment: payment, interest: interest, principal: principal, balance: bal });
      if (m === o.draw) endDraw = bal;
    }
    if (endDraw === null) endDraw = 0;
    return { rows: rows, interest: interestTotal, paid: paid, endDraw: endDraw };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function pct(v) { return (Math.round(v * 1000) / 1000) + '%'; }

  function clearResults() {
    ['eqNow', 'eqRepayPay', 'eqMax', 'eqInterest'].forEach(function (id) { setText(id, '–'); setText(id + 'Note', ''); });
    ['eqEndDraw', 'eqPayoff', 'eqTotalPaid', 'eqSaved'].forEach(function (id) { setText(id, '–'); });
    el('eqShock').hidden = true;
    el('eqTable').innerHTML = '';
  }

  function update() {
    var balance = read('eqBalance'), rate = read('eqRate'), draw = read('eqDraw', 0), repayYears = read('eqRepay'),
        change = read('eqChange', 0), extra = read('eqExtra', 0), cap = read('eqCap'), floor = read('eqFloor', 0);
    var msg = '';
    if (isNaN(balance) || balance <= 0 || balance > 1e8) msg = 'Enter the amount owed on the line, above $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(draw) || draw < 0 || draw > 360 || draw % 1 !== 0) msg = 'Enter 0 to 360 whole months left in the draw period.';
    else if (isNaN(repayYears) || repayYears < 1 || repayYears > 30 || repayYears % 1 !== 0) msg = 'Enter a repayment period of 1 to 30 whole years.';
    else if (isNaN(change) || change < -5 || change > 5) msg = 'Enter a yearly rate change from -5% to 5%.';
    else if (isNaN(cap) || cap < rate || cap > 30) msg = 'Enter a rate cap from the current rate up to 30%.';
    else if (isNaN(extra) || extra < 0 || extra > 1e7 || isNaN(floor) || floor < 0 || floor > 1e6) msg = 'Enter extra principal and a dollar minimum of $0 or more.';
    var error = el('eqError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var o = { balance: balance, rate: rate, draw: draw, repay: repayYears * 12, rule: el('eqRule').value, method: el('eqMethod').value,
              change: change, cap: cap, floor: floor, extra: extra };
    var r = run(o);
    var rows = r.rows, first = rows[0], last = rows[rows.length - 1];
    setText('eqNow', money.format(first.payment));
    setText('eqNowNote', money.format(first.interest) + ' interest and ' + money.format(first.principal) + ' principal at ' + pct(first.rate) + '.');

    var repayRow = rows[draw] || null;
    var shock = el('eqShock');
    if (draw === 0) {
      setText('eqRepayPay', money.format(first.payment));
      setText('eqRepayPayNote', 'You are already in the repayment period.');
      shock.hidden = true;
    } else if (!repayRow) {
      setText('eqRepayPay', money.format(0));
      setText('eqRepayPayNote', 'The extra payments clear the line before repayment starts.');
      shock.hidden = true;
    } else {
      var before = rows[draw - 1].payment, jump = repayRow.payment - before;
      setText('eqRepayPay', money.format(repayRow.payment));
      setText('eqRepayPayNote', 'In month ' + (draw + 1) + ', ' + (jump >= 0 ? 'up ' : 'down ') + money.format(Math.abs(jump)) + ' from the last draw-period payment.');
      shock.hidden = jump <= 0.005;
      if (!shock.hidden) setText('eqShockText', 'When the draw period ends, your payment rises from ' + money.format(before) + ' to ' + money.format(repayRow.payment) + ' a month (' + Math.round(jump / Math.max(before, 0.01) * 100) + '% more). Paying extra principal now, or more than the minimum, softens the jump.');
    }
    var maxRow = rows.reduce(function (a, b) { return b.payment > a.payment + 0.005 && b.month !== rows.length ? b : a; }, rows[0]);
    setText('eqMax', money.format(maxRow.payment));
    setText('eqMaxNote', 'In month ' + maxRow.month + ', at ' + pct(maxRow.rate) + '.');
    setText('eqInterest', money.format(r.interest));
    setText('eqInterestNote', 'Over ' + duration(last.month) + ', on top of the ' + money.format(balance) + ' you owe.');
    setText('eqEndDraw', draw === 0 ? 'Already in repayment' : money.format(r.endDraw));
    setText('eqPayoff', duration(last.month) + (last.month < draw + o.repay ? ' (' + duration(draw + o.repay - last.month) + ' early)' : ''));
    setText('eqTotalPaid', money.format(r.paid));
    if (extra > 0) {
      var o2 = {}; for (var k in o) o2[k] = o[k]; o2.extra = 0;
      var base = run(o2);
      setText('eqSaved', money.format(base.interest - r.interest));
    } else {
      setText('eqSaved', 'Add extra principal to see the saving');
    }

    el('eqTable').innerHTML = rows.map(function (x) {
      return '<tr><td>' + x.month + '</td><td>' + (x.draw ? 'Draw' : 'Repayment') + '</td><td>' + pct(x.rate) + '</td><td>' + money.format(x.payment) + '</td><td>' +
        money.format(x.interest) + '</td><td>' + money.format(x.principal) + '</td><td>' + money.format(x.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('eqForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
